function goToOfficeProgramme(date, lieu) {
  if (can('edit')) {
    toast('Aucun programme pour cette date/ce lieu — création en cours');
    window._prefillProgDate = date;
    window._prefillProgLieu = lieu || null;
    nav('#/programme-nouveau');
  } else {
    toast('Aucun programme n’a encore été préparé pour cette date');
  }
}

