const _onlineSearchToken = {};
async function fetchOnlineSuggestions(query, containerId) {
  containerId = containerId || 'online-suggestions';
  const zone = document.getElementById(containerId);
  if (!zone || !query) { if (zone) zone.innerHTML = ''; return; }
  const myToken = (_onlineSearchToken[containerId] = (_onlineSearchToken[containerId] || 0) + 1);
  try {
    const url = 'https://itunes.apple.com/search?term=' + encodeURIComponent(query + ' chant liturgique') + '&media=music&limit=5';
    const res = await fetch(url);
    if (!res.ok) throw new Error('HTTP ' + res.status);
    const data = await res.json();
    if (_onlineSearchToken[containerId] !== myToken) return; // une recherche plus récente a été lancée entre-temps
    const zoneNow = document.getElementById(containerId);
    if (!zoneNow) return; // l’utilisateur a changé de page entre-temps
    if (!data.results || !data.results.length) {
      zoneNow.innerHTML = `<p class="muted" style="text-align:center;">Aucune proposition trouvée en ligne pour « ${esc(query)} ».</p>`;
      return;
    }
    zoneNow.innerHTML = `<p class="muted" style="margin-bottom:8px;">Propositions trouvées en ligne :</p>` + data.results.map(r => `
      <div class="chant-row" style="cursor:default;">
        ${r.artworkUrl60 ? `<img src="${esc(r.artworkUrl60)}" style="width:44px;height:44px;border-radius:6px;flex-shrink:0;">` : '<div class="rib"></div>'}
        <div style="flex:1;">
          <div class="chant-title" style="font-size:14.5px;">${esc(r.trackName)}</div>
          <div class="chant-meta">${esc(r.artistName)}</div>
          ${r.previewUrl ? `<audio controls preload="none" style="width:100%;height:30px;margin-top:6px;"><source src="${esc(r.previewUrl)}"></audio>` : ''}
        </div>
        ${r.trackViewUrl ? `<a class="btn" target="_blank" href="${esc(r.trackViewUrl)}">Voir ↗</a>` : ''}
      </div>`).join('');
  } catch (e) {
    if (_onlineSearchToken[containerId] !== myToken) return;
    const zoneNow = document.getElementById(containerId);
    if (zoneNow) zoneNow.innerHTML = `<p class="muted" style="text-align:center;">Recherche en ligne indisponible pour le moment (pas de connexion, ou navigateur bloquant l’accès depuis un fichier local). Utilisez les liens ci-dessous.</p>`;
  }
}
