function renderCustomFieldInputs(entity, record) {
  const fields = (DB.schema && DB.schema[entity]) || [];
  if (!fields.length) return '';
  return fields.map(f => {
    const val = (record.custom && record.custom[f.key]) || '';
    const type = f.type === 'number' ? 'number' : (f.type === 'date' ? 'date' : 'text');
    return `<div class="field"><label>${esc(f.label)} <span class="badge gold" style="font-size:9px;">perso.</span></label><input id="custom-${f.key}" type="${type}" value="${esc(val)}"></div>`;
  }).join('');
}
function readCustomFieldValues(entity) {
  const fields = (DB.schema && DB.schema[entity]) || [];
  const out = {};
  fields.forEach(f => {
    const el = document.getElementById('custom-' + f.key);
    if (el) out[f.key] = el.value.trim() || null;
  });
  return out;
}
