function saveChant(id) {
  const val = (i) => document.getElementById(i).value.trim();
  const titre = val('f-titre');
  if (!titre) { toast('Le titre est obligatoire'); return; }
  const audios = document.getElementById('f-audios').value.split('\n')
    .map(l => l.trim()).filter(Boolean)
    .map(l => { const [label, ...rest] = l.split('|'); return { label: (label||'Piste').trim(), src: rest.join('|').trim() || null }; });
  let partitionVal = val('f-partition');
  if (/^C:\\Liturgie\\Medias\\Partitions\\?$/i.test(partitionVal)) partitionVal = '';
  const data = {
    titre, reference1: val('f-ref1')||null, reference2: val('f-ref2')||null,
    texte: val('f-texte')||null, type_messe: val('f-typemesse')||null, type_chant: val('f-typechant')||null,
    compositeur: val('f-compositeur')||null, harmonisation: val('f-harmo')||null,
    partition: partitionVal||null, youtube: val('f-youtube')||null, audios,
    custom: readCustomFieldValues('chants'),
  };
  let finalId = id;
  if (id) {
    const idx = DB.chants.findIndex(c => c.id === id);
    DB.chants[idx] = { ...DB.chants[idx], ...data };
  } else {
    finalId = DB.nextChantId++;
    DB.chants.push({ id: finalId, ...data });
  }
  window._searchDone = false; window._searchTitre = ''; window._searchRef = '';
  window._listeTitre = ''; window._listeRef = '';
  persist(); toast('Chant enregistré'); nav('#/chants/' + finalId); render();
}
